import {readFileSync, realpathSync} from 'node:fs';
import {pathToFileURL, fileURLToPath} from 'node:url';

function isNonemptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

export function planRedactions(text, rules) {
  if (typeof text !== 'string') {
    throw new Error('text must be a string');
  }
  if (!Array.isArray(rules)) {
    throw new Error('rules must be a dense array');
  }

  // Validate every rule before doing any matching, even when text is empty.
  const seenIds = new Set();
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    if (rule === null || typeof rule !== 'object' || Array.isArray(rule)) {
      throw new Error('each rule must be a non-null, non-array object');
    }
    const id = rule.id;
    if (!isNonemptyString(id)) {
      throw new Error('each rule id must be a nonempty string');
    }
    if (seenIds.has(id)) {
      throw new Error('rule ids must be unique');
    }
    seenIds.add(id);
    if (!isNonemptyString(rule.literal)) {
      throw new Error('each rule literal must be a nonempty string');
    }
    if (typeof rule.replacement !== 'string') {
      throw new Error('each rule replacement must be a string');
    }
  }

  // Collect every exact, case-sensitive literal occurrence in the ORIGINAL
  // text, including overlapping occurrences. Offsets are UTF-16 code units.
  const matches = [];
  for (let ruleIndex = 0; ruleIndex < rules.length; ruleIndex++) {
    const rule = rules[ruleIndex];
    const literal = rule.literal;
    const length = literal.length;
    let from = 0;
    for (;;) {
      const idx = text.indexOf(literal, from);
      if (idx === -1) break;
      matches.push({
        start: idx,
        end: idx + length,
        length,
        ruleIndex,
        id: rule.id,
        replacement: rule.replacement,
      });
      from = idx + 1;
    }
  }

  // Priority: earliest start first; same start -> longest literal first;
  // equal length -> earlier rule-array position first.
  matches.sort((a, b) => {
    if (a.start !== b.start) return a.start - b.start;
    if (a.length !== b.length) return b.length - a.length;
    return a.ruleIndex - b.ruleIndex;
  });

  // Greedy select: reject matches starting before the last selected edit's end.
  // Touching edits (start === lastEnd) are allowed.
  const selected = [];
  let lastEnd = 0;
  for (const match of matches) {
    if (match.start >= lastEnd) {
      selected.push(match);
      lastEnd = match.end;
    }
  }

  let redacted = '';
  let cursor = 0;
  const edits = [];
  for (const match of selected) {
    redacted += text.slice(cursor, match.start);
    redacted += match.replacement;
    edits.push({start: match.start, end: match.end, id: match.id});
    cursor = match.end;
  }
  redacted += text.slice(cursor);

  return {
    text: redacted,
    edits,
    originalBytes: Buffer.byteLength(text, 'utf8'),
    redactedBytes: Buffer.byteLength(redacted, 'utf8'),
  };
}

function isMainModule() {
  const entry = process.argv[1];
  if (typeof entry !== 'string' || entry.length === 0) return false;
  let entryUrl;
  try {
    entryUrl = pathToFileURL(entry).href;
  } catch {
    return false;
  }
  if (entryUrl === import.meta.url) return true;
  try {
    return realpathSync(fileURLToPath(import.meta.url)) ===
      realpathSync(fileURLToPath(entryUrl));
  } catch {
    return false;
  }
}

if (isMainModule()) {
  let exitCode = 0;
  try {
    const args = process.argv.slice(2);
    if (args.length !== 1) {
      throw new Error('usage: node redaction-plan.js INPUT_JSON_FILE');
    }
    const raw = readFileSync(args[0], 'utf8');
    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch {
      throw new Error('input file must contain valid JSON');
    }
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      throw new Error('input JSON must be a non-null, non-array object');
    }
    const result = planRedactions(parsed.text, parsed.rules);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (err) {
    process.stderr.write((err instanceof Error ? err.message : String(err)) + '\n');
    exitCode = 2;
  }
  process.exitCode = exitCode;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {planRedactions} from '../redaction-plan.js';
import {spawnSync} from 'node:child_process';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';

const modulePath = fileURLToPath(new URL('../redaction-plan.js', import.meta.url));

test('spec example selects earliest start then longest then rule order', () => {
  const res = planRedactions('ababa', [
    {id: 'long', literal: 'aba', replacement: 'X'},
    {id: 'short', literal: 'ba', replacement: 'Y'},
  ]);
  assert.deepEqual(res, {
    text: 'XY',
    edits: [{start: 0, end: 3, id: 'long'}, {start: 3, end: 5, id: 'short'}],
    originalBytes: 5,
    redactedBytes: 2,
  });
});

test('overlapping occurrences of a single literal', () => {
  const res = planRedactions('aaaa', [{id: 'a', literal: 'aa', replacement: 'X'}]);
  assert.equal(res.text, 'XX');
  assert.deepEqual(res.edits, [
    {start: 0, end: 2, id: 'a'},
    {start: 2, end: 4, id: 'a'},
  ]);
});

test('overlapping occurrences that are all rejected after first pick', () => {
  // 'aaa' contains 'aa' at 0 and 1; only the earliest survives.
  const res = planRedactions('aaa', [{id: 'a', literal: 'aa', replacement: 'X'}]);
  assert.equal(res.text, 'Xa');
  assert.deepEqual(res.edits, [{start: 0, end: 2, id: 'a'}]);
});

test('equal length same start falls back to earlier rule position', () => {
  const res = planRedactions('zz', [
    {id: 'first', literal: 'zz', replacement: 'F'},
    {id: 'second', literal: 'zz', replacement: 'S'},
  ]);
  assert.equal(res.text, 'F');
  assert.deepEqual(res.edits, [{start: 0, end: 2, id: 'first'}]);
});

test('touching edits are allowed', () => {
  const res = planRedactions('abc', [
    {id: 'ab', literal: 'ab', replacement: 'X'},
    {id: 'c', literal: 'c', replacement: 'Y'},
  ]);
  assert.equal(res.text, 'XY');
  assert.deepEqual(res.edits, [
    {start: 0, end: 2, id: 'ab'},
    {start: 2, end: 3, id: 'c'},
  ]);
});

test('replacement text is never reprocessed', () => {
  const res = planRedactions('a', [
    {id: 'to', literal: 'a', replacement: 'aa'},
    {id: 'from', literal: 'aa', replacement: 'B'},
  ]);
  // 'aa' is produced only by replacement, so 'from' must not match.
  assert.equal(res.text, 'aa');
  assert.deepEqual(res.edits, [{start: 0, end: 1, id: 'to'}]);
});

test('ids are opaque, including __proto__', () => {
  const res = planRedactions('x', [{id: '__proto__', literal: 'x', replacement: 'Z'}]);
  assert.equal(res.edits.length, 1);
  assert.equal(res.edits[0].id, '__proto__');
  assert.deepEqual(res.edits, [{start: 0, end: 1, id: '__proto__'}]);
  assert.equal(JSON.parse(JSON.stringify(res.edits))[0].id, '__proto__');
});

test('byte counts use utf8 code points, offsets use code units', () => {
  // 'é' is 1 code unit, 2 bytes in utf8. Surrogate pair '𝐀' is 2 code units, 4 bytes.
  const res = planRedactions('é𝐀', [
    {id: 'e', literal: 'é', replacement: 'x'},
    {id: 'a', literal: '𝐀', replacement: 'y'},
  ]);
  assert.equal(res.text, 'xy');
  assert.deepEqual(res.edits, [
    {start: 0, end: 1, id: 'e'},
    {start: 1, end: 3, id: 'a'},
  ]);
  assert.equal(res.originalBytes, 2 + 4);
  assert.equal(res.redactedBytes, 2);
});

test('empty replacement and empty text', () => {
  assert.deepEqual(
    planRedactions('', [{id: 'x', literal: 'a', replacement: 'b'}]),
    {text: '', edits: [], originalBytes: 0, redactedBytes: 0},
  );
  const res = planRedactions('abc', [{id: 'b', literal: 'b', replacement: ''}]);
  assert.equal(res.text, 'ac');
  assert.deepEqual(res.edits, [{start: 1, end: 2, id: 'b'}]);
  assert.equal(res.redactedBytes, 2);
});

test('does not mutate inputs and works with frozen inputs', () => {
  const text = Object.freeze('ababa');
  const rule = Object.freeze({id: 'long', literal: 'aba', replacement: 'X'});
  const rules = Object.freeze([rule]);
  const snapshot = JSON.parse(JSON.stringify(rules));
  const res = planRedactions(text, rules);
  assert.equal(res.text, 'Xba');
  assert.deepEqual(rules, snapshot);
  assert.deepEqual(rule, {id: 'long', literal: 'aba', replacement: 'X'});
});

test('invalid inputs throw', () => {
  assert.throws(() => planRedactions(null, []), Error);
  assert.throws(() => planRedactions(123, []), Error);
  assert.throws(() => planRedactions('', null), Error);
  assert.throws(() => planRedactions('', {}), Error);
  assert.throws(() => planRedactions('', [null]), Error);
  assert.throws(() => planRedactions('', [[]]), Error);
  assert.throws(() => planRedactions('', [1]), Error);
  assert.throws(() => planRedactions('', [{id: '', literal: 'a', replacement: ''}]), Error);
  assert.throws(() => planRedactions('', [{id: 'a', literal: '', replacement: ''}]), Error);
  assert.throws(() => planRedactions('', [{id: 'a', literal: 'a', replacement: 1}]), Error);
  assert.throws(
    () =>
      planRedactions('', [
        {id: 'a', literal: 'x', replacement: ''},
        {id: 'a', literal: 'y', replacement: ''},
      ]),
    Error,
  );
  // Validation happens even when text is empty.
  assert.throws(() => planRedactions('', [{id: 'a', literal: 'a'}]), Error);
});

test('return value has exactly the documented shape', () => {
  const res = planRedactions('abc', [{id: 'b', literal: 'b', replacement: 'B', extra: 1}]);
  assert.deepEqual(Object.keys(res).sort(), ['edits', 'originalBytes', 'redactedBytes', 'text']);
  assert.deepEqual(Object.keys(res.edits[0]).sort(), ['end', 'id', 'start']);
});

function runCli(args) {
  return spawnSync(process.execPath, [modulePath, ...args], {encoding: 'utf8'});
}

function withTempFile(content, fn) {
  const dir = mkdtempSync(join(tmpdir(), 'redaction-plan-'));
  const file = join(dir, 'input.json');
  try {
    writeFileSync(file, content, 'utf8');
    return fn(file);
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
}

test('cli prints the API result and exits 0', () => {
  withTempFile(
    JSON.stringify({
      text: 'ababa',
      rules: [
        {id: 'long', literal: 'aba', replacement: 'X'},
        {id: 'short', literal: 'ba', replacement: 'Y'},
      ],
      ignored: true,
    }),
    (file) => {
      const r = runCli([file]);
      assert.equal(r.status, 0);
      assert.equal(r.stderr, '');
      assert.ok(r.stdout.endsWith('\n'));
      assert.deepEqual(JSON.parse(r.stdout), {
        text: 'XY',
        edits: [
          {start: 0, end: 3, id: 'long'},
          {start: 3, end: 5, id: 'short'},
        ],
        originalBytes: 5,
        redactedBytes: 2,
      });
    },
  );
});

test('cli with no args exits 2, no stdout, nonempty stderr', () => {
  const r = runCli([]);
  assert.equal(r.status, 2);
  assert.equal(r.stdout, '');
  assert.ok(r.stderr.length > 0);
});

test('cli with two args exits 2', () => {
  const r = runCli(['a.json', 'b.json']);
  assert.equal(r.status, 2);
  assert.equal(r.stdout, '');
  assert.ok(r.stderr.length > 0);
});

test('cli missing file exits 2', () => {
  const r = runCli([join(tmpdir(), 'definitely-not-here.json')]);
  assert.equal(r.status, 2);
  assert.equal(r.stdout, '');
  assert.ok(r.stderr.length > 0);
});

test('cli invalid JSON exits 2', () => {
  withTempFile('{not json', (file) => {
    const r = runCli([file]);
    assert.equal(r.status, 2);
    assert.equal(r.stdout, '');
    assert.ok(r.stderr.length > 0);
  });
});

test('cli top-level array/null exits 2', () => {
  withTempFile('[1,2,3]', (file) => {
    assert.equal(runCli([file]).status, 2);
  });
  withTempFile('null', (file) => {
    assert.equal(runCli([file]).status, 2);
  });
});

test('cli invalid API input exits 2', () => {
  withTempFile(JSON.stringify({text: 'x'}), (file) => {
    const r = runCli([file]);
    assert.equal(r.status, 2);
    assert.equal(r.stdout, '');
    assert.ok(r.stderr.length > 0);
  });
  withTempFile(JSON.stringify({text: 1, rules: []}), (file) => {
    assert.equal(runCli([file]).status, 2);
  });
});

test('importing the module does not run the CLI', () => {
  // If the CLI ran on import, this import above would have thrown or printed.
  assert.equal(typeof planRedactions, 'function');
});

