+        length,
+        ruleIndex,
+        id: rule.id,
+        replacement: rule.replacement,
+      });
+      from = idx + 1;
+    }
+  }
+
+  // Priority: earliest start first; same start -> longest literal first;
+  // equal length -> earlier rule-array position first.
+  matches.sort((a, b) => {
+    if (a.start !== b.start) return a.start - b.start;
+    if (a.length !== b.length) return b.length - a.length;
+    return a.ruleIndex - b.ruleIndex;
+  });
+
+  // Greedy select: reject matches starting before the last selected edit's end.
+  // Touching edits (start === lastEnd) are allowed.
+  const selected = [];
+  let lastEnd = 0;
+  for (const match of matches) {
+    if (match.start >= lastEnd) {
+      selected.push(match);
+      lastEnd = match.end;
+    }
+  }
+
+  let redacted = '';
+  let cursor = 0;
+  const edits = [];
+  for (const match of selected) {
+    redacted += text.slice(cursor, match.start);
+    redacted += match.replacement;
+    edits.push({start: match.start, end: match.end, id: match.id});
+    cursor = match.end;
+  }
+  redacted += text.slice(cursor);
+
+  return {
+    text: redacted,
+    edits,
+    originalBytes: Buffer.byteLength(text, 'utf8'),
+    redactedBytes: Buffer.byteLength(redacted, 'utf8'),
+  };
+}
+
+function isMainModule() {
+  const entry = process.argv[1];
+  if (typeof entry !== 'string' || entry.length === 0) return false;
+  let entryUrl;
+  try {
+    entryUrl = pathToFileURL(entry).href;
+  } catch {
+    return false;
+  }
+  if (entryUrl === import.meta.url) return true;
+  try {
+    return realpathSync(fileURLToPath(import.meta.url)) ===
+      realpathSync(fileURLToPath(entryUrl));
+  } catch {
+    return false;
+  }
+}
+
+if (isMainModule()) {
+  let exitCode = 0;
+  try {
+    const args = process.argv.slice(2);
+    if (args.length !== 1) {
+      throw new Error('usage: node redaction-plan.js INPUT_JSON_FILE');
+    }
+    const raw = readFileSync(args[0], 'utf8');
+    let parsed;
+    try {
+      parsed = JSON.parse(raw);
+    } catch {
+      throw new Error('input file must contain valid JSON');
+    }
+    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
+      throw new Error('input JSON must be a non-null, non-array object');
+    }
+    const result = planRedactions(parsed.text, parsed.rules);
+    process.stdout.write(JSON.stringify(result) + '\n');
+  } catch (err) {
+    process.stderr.write((err instanceof Error ? err.message : String(err)) + '\n');
+    exitCode = 2;
+  }
+  process.exitCode = exitCode;
+}

